#include "weather/client.h"

#include <stdio.h>
#include <stdlib.h>

/* The client asks for the token on every attempt, so a refreshed one is used. */
static weather_status read_token(void *user, const weather_scope *scope, weather_arena *arena,
    bool *present, weather_string *token, weather_error *error) {
    const char *value = getenv("WEATHER_TOKEN");
    (void)user;
    (void)scope;
    (void)arena;
    (void)error;
    *present = value != NULL;
    *token = weather_string_view(value);
    return weather_ok;
}

int main(void) {
    weather_error error = {0};
    /* The client sends Authorization: Bearer <token> and Crucible-Version: 2026-10-01 on every request. */
    weather_client_config config = weather_client_defaults();
    config.endpoint = weather_string_view(getenv("WEATHER_ENDPOINT"));
    config.token = read_token;
    weather_client *client = NULL;
    if (weather_client_new(&config, &client, &error) != weather_ok) {
        fprintf(stderr, "weather_client_new: %s\n", error.message);
        return 1;
    }

    /* Values from the model's example "Create a city". */
    weather_models_coordinates input_location_coordinates = {0};
    weather_models_coordinates_set_latitude(&input_location_coordinates, 38.72);
    weather_models_coordinates_set_longitude(&input_location_coordinates, -9.14);
    weather_models_location input_location = {.tag = weather_models_location_tag_coordinates, .state = weather_present, .value.coordinates = &input_location_coordinates};
    weather_models_create_city_input input = {0};
    weather_models_create_city_input_set_name(&input, weather_string_view("Lisbon"));
    weather_models_create_city_input_set_location(&input, &input_location);
    weather_models_create_city_input_set_expected_revision(&input, 7);

    weather_operations_create_city_result result = {0};
    weather_status status = weather_operations_create_city(client, &input, NULL, NULL, &result, &error);
    if (status == weather_ok) {
        weather_string text = {0};
        if (weather_models_city_summary_debug(result.base.arena, weather_models_create_city_output_get_city(result.value), &text, &error) == weather_ok) printf("city: %.*s\n", (int)text.length, text.data);
    } else if (weather_error_as_conflict_error(&result.base) != NULL) {
        weather_string text = {0};
        const weather_models_conflict_error *failure = weather_error_as_conflict_error(&result.base);
        fprintf(stderr, "ConflictError (HTTP %d)\n", result.base.response.status);
        text = weather_models_conflict_error_get_message(failure);
        fprintf(stderr, "message: %.*s\n", (int)text.length, text.data);
    } else {
        fprintf(stderr, "CreateCity failed: %s\n", error.message);
    }
    weather_operations_create_city_result_free(&result);
    weather_client_free(client);
    return status == weather_ok ? 0 : 1;
}

