#include "weather/client.hpp"

#include <cstdlib>
#include <iostream>
#include <optional>
#include <string>

namespace sdk = example::weather;

int main() {
    // The client sends Authorization: Bearer <token> and Crucible-Version: 2026-10-01 on every request.
    sdk::runtime::ClientConfig config;
    if (const char* endpoint = std::getenv("WEATHER_ENDPOINT")) config.endpoint = endpoint;
    config.token = [] {
        const char* token = std::getenv("WEATHER_TOKEN");
        return token ? std::optional<std::string>(token) : std::nullopt;
    };
    sdk::WeatherClient client(config);

    // Values from the model's example "Create a city".
    const sdk::models::CreateCityInput input(
        "Lisbon",
        sdk::models::Location{sdk::models::LocationCoordinatesVariant{sdk::models::Coordinates(38.72, -9.14)}},
        {},
        7);

    try {
        const auto output = client.create_city(input);
        std::cout << "city: " << sdk::runtime::debug_value(output.city) << '\n';
    } catch (const sdk::models::ConflictError& error) {
        std::cerr << "ConflictError (HTTP " << error.metadata().status << "): " << error.message << '\n';
        return 1;
    }
    return 0;
}

