package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"os"

	"example.com/weather"
)

func main() {
	ctx := context.Background()
	// The client sends Authorization: Bearer <token> and Crucible-Version: 2026-10-01 on every request.
	client, err := weather.NewWeatherClient(weather.Config{
		Endpoint: os.Getenv("WEATHER_ENDPOINT"),
		Token:    func(context.Context) (string, error) { return os.Getenv("WEATHER_TOKEN"), nil },
	})
	if err != nil {
		log.Fatal(err)
	}

	// Values from the model's example "Create a city".
	input := &weather.CreateCityInput{
		Name: "Lisbon",
		Location: weather.Some(&weather.Location{
			Coordinates: weather.Some(&weather.Coordinates{
				Latitude:  38.72,
				Longitude: -9.14,
			}),
		}),
		ExpectedRevision: weather.Some(int64(7)),
	}

	output, err := client.CreateCity(ctx, input)
	var conflictError *weather.ConflictError
	if errors.As(err, &conflictError) {
		fmt.Printf("ConflictError (HTTP %d): %v\n", conflictError.Metadata.Metadata.Status, conflictError.Message)
		return
	}
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(output.City)
}

