use weather_sdk::*;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // The client sends Authorization: Bearer <token> and Crucible-Version: 2026-10-01 on every request.
    let client = WeatherClient::new(
        runtime::Config::new(std::env::var("WEATHER_ENDPOINT")?)
            .token(runtime::Token::fixed(std::env::var("WEATHER_TOKEN")?)),
    );

    // Values from the model's example "Create a city".
    let input = CreateCityInput::builder()
        .name("Lisbon")
        .location(Location::Coordinates(Coordinates::builder()
            .latitude(38.72)
            .longitude(-9.14)
            .build()?))
        .expected_revision(7_i64)
        .build()?;

    match client.create_city(input).await {
        Ok(output) => {
            println!("{:?}", output.city());
        }
        Err(runtime::Error::Service(runtime::ServiceError {
            error: CreateCityError::ConflictError(error),
            metadata,
        })) => {
            eprintln!("ConflictError (HTTP {}): {:?}", metadata.status, error.message());
        }
        Err(error) => return Err(error.into()),
    }
    Ok(())
}

